#!/usr/bin/env bash
set -euo pipefail
WORKSPACE="/home/kavia/workspace/code-generation/uttar-pradesh-tourism-infrastructure-management-system-40496-40506/spring_backend"
cd "$WORKSPACE"
command -v mvn >/dev/null 2>&1 || { echo "mvn not found" >&2; exit 2; }
# Build executable jar deterministically (finalName set in pom)
mvn -B -q -DskipTests package || { echo "mvn package failed" >&2; exit 3; }
JAR="$WORKSPACE/target/$(basename "$(pwd)")-0.0.1-SNAPSHOT.jar"
# fallback: find file by finalName pattern
if [ ! -f "$JAR" ]; then JAR=$(ls -1 target/*.jar 2>/dev/null | grep -v 'original' | head -n1 || true); fi
[ -n "$JAR" ] && [ -f "$JAR" ] || { echo "executable jar not found in target" >&2; exit 4; }
echo "$JAR"

